  "solucion": "BEGIN TRAN;\nUPDATE pedidos SET estado = 'cancelado' WHERE estado = 'pendiente' AND fecha < '2026-04-01';\nCOMMIT;\nSELECT estado, COUNT(*) AS pedidos FROM pedidos GROUP BY estado;",
